// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem

	refresh func() // callback to trigger menu UI update
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh triggers a visual update of the menu if it is currently displayed.
// This is useful when menu items have changed dynamically.
//
// Since: 2.2
func (m *Menu) Refresh() {
	if m.refresh != nil {
		m.refresh()
	}
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Icon is the icon to display next to the menu item.
	//
	// Since: 2.2
	Icon Resource
	// Shortcut is the keyboard shortcut for this menu item.
	//
	// Since: 2.2
	Shortcut Shortcut

	refresh func() // callback to trigger menu item UI update
}

// NewMenuItem creates a new menu item from the passed label and action parameters.
func NewMenuItem(label string, action func()) *MenuItem {
	return &MenuItem{Label: label, Action: action}
}

// Refresh triggers a visual update of this menu item if it is currently displayed.
// This is useful when item properties (like Checked, Disabled, Icon) have changed.
//
// Since: 2.2
func (m *MenuItem) Refresh() {
	if m.refresh != nil {
		m.refresh()
	}
}

// NewMenuItemSeparator creates a menu item that is to be used as a separator.
func NewMenuItemSeparator() *MenuItem {
	return &MenuItem{IsSeparator: true, Action: func() {}}
}

// MainMenu defines the data required to show a menu bar (desktop) or other appropriate top level menu.
type MainMenu struct {
	Items []*Menu

	refresh func() // callback to trigger main menu UI update
}

// NewMainMenu creates a top level menu structure used by fyne.Window for displaying a menubar
// (or appropriate equivalent).
func NewMainMenu(items ...*Menu) *MainMenu {
	return &MainMenu{Items: items}
}

// Refresh triggers a visual update of the main menu if it is currently displayed.
// This is useful when the menu structure has changed dynamically.
//
// Since: 2.2
func (m *MainMenu) Refresh() {
	if m.refresh != nil {
		m.refresh()
	}
}
