import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that checks if the input matches one of the allowed strings.
// The validator will return nil if the input matches any string in the allowed list,
// otherwise returns an error with the provided reason.
//
// Since: 2.2
func NewAllStrings(allowed []string, reason string) fyne.StringValidator {
	if len(allowed) == 0 {
		return func(text string) error {
			return errors.New(reason)
		}
	}

	return func(text string) error {
		for _, s := range allowed {
			if text == s {
				return nil
			}
		}
		return errors.New(reason)
	}
}
